<?php
declare(strict_types=1);
namespace WexaShelf;
use PDO;
final class StoreObservations {
    public function __construct(private PDO $db,private Repository $repo){}
    public function capture(array $record):void {
        if($record['kind']!=='app'||($record['status']!=='published'&&!($record['status']==='scheduled'&&!empty($record['publishAt'])&&strtotime($record['publishAt'])<=time())))return;
        $key='store-observations:'.$record['id'];$rows=$this->repo->setting($key,[]);$seen=[];foreach($rows as $row)$seen[($row['storeId']??'').':'.$row['platform'].':'.$row['country'].':'.$row['observedAt']]=true;
        foreach($record['data']['storeMetrics']??[] as $metric){Validation::check(strtotime($metric['observedAt'])<=time()+300,'Store observations cannot be future dated.');$identity=null;foreach($record['data']['storeIds']??[] as $store)if($store['platform']===$metric['platform']&&$store['country']===$metric['country'])$identity=$store['storeId'];$id=($identity??'').':'.$metric['platform'].':'.$metric['country'].':'.$metric['observedAt'];if(isset($seen[$id]))continue;$rows[]=array_merge($metric,['appId'=>$record['id'],'storeId'=>$identity]);$seen[$id]=true;}
        usort($rows,fn($a,$b)=>strcmp($a['observedAt'],$b['observedAt']));$this->repo->setSetting($key,array_slice($rows,-1000));
    }
    public function all():array{$q=$this->db->query("SELECT value FROM ws_settings WHERE setting_key LIKE 'store-observations:%'");$out=[];foreach($q->fetchAll() as $row)array_push($out,...json_decode($row['value'],true,64,JSON_THROW_ON_ERROR));return $out;}
    public function publicData(array $apps):array {$out=[];foreach($apps as $app){$identities=[];foreach($app['storeIds']??[]as$store)$identities[$store['platform'].':'.$store['country']]=$store['storeId'];foreach($this->repo->setting('store-observations:'.$app['id'],[]) as $row)if(($row['storeId']??null)===($identities[$row['platform'].':'.$row['country']]??null))$out[]=$row;}return$out;}
    public static function validateBackup(mixed $input):array {
        if($input===null)return [];$rows=Validation::items($input,'store observations',100000);$seen=[];$perApp=[];foreach($rows as $row){Validation::check(is_array($row)&&!array_diff(array_keys($row),['appId','storeId','platform','country','downloadsLowerBound','rating','ratingCount','sourceUrl','observedAt']),'Invalid store observation fields.');Validation::check(is_string($row['appId']??null)&&preg_match('/^[a-z0-9][a-z0-9-]{0,79}$/D',$row['appId'])&&in_array($row['platform']??null,Validation::PLATFORMS,true)&&Validation::country($row['country']??null),'Invalid store identity.');Validation::check(($row['storeId']??null)===null||is_string($row['storeId'])&&strlen($row['storeId'])<=255,'Invalid store ID.');Validation::url($row['sourceUrl']??null);Validation::date($row['observedAt']??null);Validation::check(strtotime($row['observedAt'])<=time()+300,'Store observations cannot be future dated.');foreach(['downloadsLowerBound','rating','ratingCount'] as $metric){$value=$row[$metric]??null;Validation::check(array_key_exists($metric,$row)&&($value===null||(is_int($value)||is_float($value))&&is_finite((float)$value)&&$value>=0&&$value<=($metric==='rating'?5:9007199254740991)),'Invalid metric.');}$key=$row['appId'].':'.($row['storeId']??'').':'.$row['platform'].':'.$row['country'].':'.$row['observedAt'];Validation::check(!isset($seen[$key]),'Duplicate observation.');$seen[$key]=true;$perApp[$row['appId']]=($perApp[$row['appId']]??0)+1;Validation::check($perApp[$row['appId']]<=1000,'Too many app observations.');}return $rows;
    }
    public function restoreBackup(array $rows):void {$rows=self::validateBackup($rows);$this->db->exec("DELETE FROM ws_settings WHERE setting_key LIKE 'store-observations:%'");$groups=[];foreach($rows as $row)$groups[$row['appId']][]=$row;foreach($groups as $id=>$group){Validation::check(count($group)<=1000,'Too many app observations.');$this->repo->setSetting('store-observations:'.$id,$group);}}
}
